CREATE TABLE public.items (
    key text NOT NULL,
    label text NOT NULL,
    tier text NOT NULL,
    "group" text NOT NULL,
    group_weight_note text,
    numbeo_equivalent text,
    normal_unit text NOT NULL,
    target_size jsonb NOT NULL,
    match jsonb NOT NULL,
    categories jsonb NOT NULL,
    min_base_quantity double precision,
    min_base_quantity_note text,
    spec_version integer DEFAULT 1 NOT NULL,
    index_quantity double precision,
    index_uom text,
    CONSTRAINT items_index_uom_matches_normal_unit CHECK ((((index_quantity IS NULL) AND (index_uom IS NULL)) OR ((index_quantity > (0)::double precision) AND (index_uom =
CASE normal_unit
    WHEN 'g'::text THEN 'kg'::text
    WHEN 'ml'::text THEN 'l'::text
    ELSE 'count'::text
END))))
);
