CREATE VIEW public.latest_price AS
 SELECT DISTINCT ON (store_id, product_key) id,
    run_id,
    store_id,
    product_key,
    observed_at,
    price,
    currency,
    unit_price,
    unit_price_basis,
    in_stock,
    change,
    previous_price,
    delta
   FROM public.price_observations
  ORDER BY store_id, product_key, id DESC;
