DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trgm') THEN
    CREATE INDEX IF NOT EXISTS idx_products_name_trgm
      ON public.products USING gin (name public.gin_trgm_ops);
  END IF;
END $$;
